#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    if (cin >> n) {
        vector<int> q;
        for(int i = 0; i < n; ++i) {
            int x;
            cin >> x;
            // lower_bound 返回第一个大于等于 x 的元素的迭代器
            auto it = lower_bound(q.begin(), q.end(), x);
            if (it == q.end()) {
                q.push_back(x);
            } else {
                *it = x;
            }
        }
        cout << q.size() << "\n";
    }
    return 0;
}
